using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Eval;

/// <summary>
/// Shared setup for evaluation runs: telemetry, quality evaluators, and comparison.
/// </summary>
public static class EvalSetup
{
    private static readonly ActivitySource ActivitySource = new("MyApp.Eval");

    /// <summary>
    /// Configures OpenTelemetry tracing for eval telemetry mode.
    /// </summary>
    public static TracerProvider CreateTelemetryProvider()
    {
        var endpoint = Environment.GetEnvironmentVariable("OTEL_EXPORTER_OTLP_ENDPOINT")
            ?? "http://localhost:4317";

        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault()
                .AddService("myapp-coach-eval"))
            .AddSource("MyApp.Eval")
            .AddSource("Microsoft.Extensions.AI")
            .AddOtlpExporter(opts => opts.Endpoint = new Uri(endpoint))
            .Build()!;
    }

    /// <summary>
    /// Creates the quality evaluators used to judge agent responses.
    /// </summary>
    public static IList<IEvaluator> CreateQualityEvaluators()
    {
        return new List<IEvaluator>
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new CompletenessEvaluator(),
            new GroundednessEvaluator(),
        };
    }

    /// <summary>
    /// Creates a report store for persisting evaluation results (used by compare mode).
    /// </summary>
    public static DiskBasedReportingConfiguration CreateReportingConfig(string resultsDir)
    {
        return DiskBasedReportingConfiguration.Create(storageRootPath: resultsDir);
    }

    public static Activity? StartActivity(string name)
        => ActivitySource.StartActivity(name);
}

using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Telemetry mode: validates that agent interactions emit structured traces.
/// </summary>
[TestClass]
public class TelemetryTests
{
    [TestMethod]
    public async Task Agent_Interaction_Emits_Traces()
    {
        using var tracer = EvalSetup.CreateTelemetryProvider();
        using var activity = EvalSetup.StartActivity("eval.telemetry.greeting");

        Assert.IsNotNull(activity, "Telemetry activity should be created");
        activity?.SetTag("eval.scenario", "greeting");
        activity?.SetTag("eval.input", "Hello, I need help getting started.");

        // Simulate agent call — replace with actual Coach invocation when integrated
        await Task.Delay(10);

        activity?.SetTag("eval.status", "completed");
        activity?.SetStatus(System.Diagnostics.ActivityStatusCode.Ok);
    }

    [TestMethod]
    public async Task Agent_Interaction_Records_Token_Usage()
    {
        using var tracer = EvalSetup.CreateTelemetryProvider();
        using var activity = EvalSetup.StartActivity("eval.telemetry.token_usage");

        Assert.IsNotNull(activity);
        activity?.SetTag("eval.scenario", "explanation");
        activity?.SetTag("eval.input", "Explain how dependency injection works in .NET.");

        await Task.Delay(10);

        // Token usage tags would be set by the AI middleware automatically
        activity?.SetTag("gen_ai.usage.prompt_tokens", 25);
        activity?.SetTag("gen_ai.usage.completion_tokens", 150);
        activity?.SetStatus(System.Diagnostics.ActivityStatusCode.Ok);
    }
}

