using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Eval;

/// <summary>
/// Quality mode: scores agent responses using LLM-as-judge evaluators.
/// </summary>
[TestClass]
public class QualityTests
{
    private const double Threshold = 3.0;

    [TestMethod]
    public async Task Greeting_Response_Meets_Quality_Thresholds()
    {
        var evaluators = EvalSetup.CreateQualityEvaluators();
        var chatHistory = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, I need help getting started."),
        };

        // Simulated agent response - replace with actual Coach invocation
        var modelResponse = new ChatMessage(
            ChatRole.Assistant,
            "Welcome! I'm here to help you get started. What would you like to work on today?");

        var context = new EvaluationContext();
        foreach (var evaluator in evaluators)
        {
            await evaluator.EvaluateAsync(chatHistory, modelResponse, context);
        }

        foreach (var (name, result) in context.Diagnostics)
        {
            if (result is NumericMetric numeric)
            {
                Assert.IsTrue(
                    numeric.Value >= Threshold,
                    $"{name} score {numeric.Value} is below threshold {Threshold}");
            }
